"""Synthetic orders with group points (invented names): a § with a table of enrolled people, a § with a long list of lines in one item."""
import sys,os,random
from docx import Document
OUT=(sys.argv[1] if len(sys.argv)>1 else 'groupcases').rstrip('/')+'/';os.makedirs(OUT,exist_ok=True)
random.seed(7)
SN=['Алмазов','Березин','Ветров','Громов','Дубов','Елагин','Жуков','Зимин','Ильин','Котов','Лосев','Мишин','Носов','Орлов','Панов','Рябов','Соколов','Титов','Уваров','Фомин']
NM=['Иван','Пётр','Сергей','Андрей','Олег','Денис','Максим','Роман']
PT=['Иванович','Петрович','Сергеевич','Андреевич','Олегович']
gen={'Иван':'Ивана','Пётр':'Петра','Сергей':'Сергея','Андрей':'Андрея','Олег':'Олега','Денис':'Дениса','Максим':'Максима','Роман':'Романа'}
ppl=[(SN[i%20]+('' if i<20 else str(i//20)),NM[i%8],PT[i%5]) for i in range(40)]
ppl=[(s if not s[-1].isdigit() else s[:-1]+'ин'*0+'', n,p) for s,n,p in ppl]
ppl=list({(s,n,p) for s,n,p in ppl});ppl.sort()
d=Document()
for t in ['ПРИКАЗ','КОМАНДИРА ВОЙСКОВОЙ ЧАСТИ 33333','по строевой части','« 27 » сентября 2022 г. № 203','г. Энск','','§ 20',
 'Нижепоименованный личный состав, призванный на военную службу по мобилизации, прибывший из военного комиссариата, зачислить в списки личного состава воинской части, на все виды обеспечения и полагать приступившим к исполнению служебных обязанностей с 27 сентября 2022 года:']:
  d.add_paragraph(t)
tb=d.add_table(rows=1,cols=4);h=tb.rows[0].cells;h[0].text='№ п/п';h[1].text='Воинское звание';h[2].text='Фамилия, имя, отчество';h[3].text='Личный номер'
for i,(s,n,p) in enumerate(ppl):
  c=tb.add_row().cells;c[0].text=str(i+1);c[1].text='рядовой';c[2].text=f'{s} {n} {p}';c[3].text=f'ГК-{400100+i}'
for t in ['Основание: именной список военного комиссариата от 26.09.2022 № 15.','','§ 21',
 '1. Полагать прибывшими из командировки и приступившими к исполнению обязанностей с 26 сентября 2022 года следующих военнослужащих:',
 ]:d.add_paragraph(t)
for i,(s,n,p) in enumerate(ppl[:12]):d.add_paragraph(f'рядового {s}а {gen[n]} {p}а, ГК-{400100+i};')
for t in ['Основание: командировочные удостоверения.','2. Рядового Особнякова Тимура Ильича полагать убывшим в отпуск с 28 сентября 2022 года.','Основание: рапорт.','','КОМАНДИР ВОЙСКОВОЙ ЧАСТИ 33333','полковник','А.Энский']:
  d.add_paragraph(t)
d.save(OUT+'Приказ 203 от 27.09.2022.docx')
print(ppl[3],ppl[5])
